begin;
select no_plan();
select has_table('reminder_private','scheduler_config','scheduler control is stored in private schema');
select has_table('reminder_private','scheduler_invocations','single-use calls have private operational records');
insert into reminder_private.scheduler_invocations(nonce,issued_at,operation) values
('77777777-7777-4777-8777-777777777777',floor(extract(epoch from now()))::bigint,'probe');
set local role service_role;
select is(public.consume_reminder_invocation('77777777-7777-4777-8777-777777777777',floor(extract(epoch from now()))::bigint,'probe'),true,'service consumes a scheduled invocation');
select is(public.consume_reminder_invocation('77777777-7777-4777-8777-777777777777',floor(extract(epoch from now()))::bigint,'probe'),false,'replay cannot consume again');
select throws_ok($$select * from reminder_private.scheduler_invocations$$,'42501',null,'service cannot read invocation table directly');
set local role authenticated;
select throws_ok($$select public.consume_reminder_invocation('77777777-7777-4777-8777-777777777777',floor(extract(epoch from now()))::bigint,'probe')$$,'42501',null,'user cannot consume scheduled calls');
select throws_ok($$select * from reminder_private.scheduler_config$$,'42501',null,'user cannot change or read scheduler settings');
reset role;
select lives_ok($$select reminder_private.prepare_scheduler()$$,'administrator can prepare inactive job');
select is((select active from cron.job where jobname='prazo-claro-reminders'),false,'prepared job is inactive');
select is((select enabled from reminder_private.scheduler_config),false,'processing defaults disabled');
select lives_ok($$select reminder_private.prepare_scheduler()$$,'preparation may be repeated');
select is((select count(*) from cron.job where jobname='prazo-claro-reminders'),1::bigint,'preparation never duplicates the job');
select lives_ok($$select reminder_private.dispatch_tick(false)$$,'disabled scheduler tick is safe');
select is(reminder_private.dispatch_tick(false),null::uuid,'disabled tick does not enqueue work');
select vault.create_secret('fictitious-scheduler-secret-at-least-32-chars','prazo_claro_scheduler_secret');
select lives_ok($$select reminder_private.dispatch_tick(true)$$,'administrator can issue a signed probe while dispatch is disabled');
select is((select headers ? 'Authorization' from net.http_request_queue where id=(select request_id from reminder_private.scheduler_invocations where request_id is not null)),false,'no permanent Bearer travels through readable queue');
select ok((select headers::text not like '%fictitious-scheduler-secret%' from net.http_request_queue where id=(select request_id from reminder_private.scheduler_invocations where request_id is not null)),'queued headers contain no signing secret');
select is((select convert_from(body,'UTF8')::jsonb->>'operation' from net.http_request_queue where id=(select request_id from reminder_private.scheduler_invocations where request_id is not null)),'probe','probe cannot become dispatch without a new signature');
select ok((select (headers->>'X-Prazo-Signature') ~ '^[a-f0-9]{64}$' from net.http_request_queue where id=(select request_id from reminder_private.scheduler_invocations where request_id is not null)),'queued capability has fixed HMAC format');
select is(reminder_private.dispatch_tick(true),null::uuid,'an in-flight probe does not create a second request');
insert into reminder_private.scheduler_invocations(nonce,issued_at,operation,created_at) values
('88888888-8888-4888-8888-888888888888',floor(extract(epoch from now()))::bigint-180,'dispatch',now()-interval '3 minutes');
set local role service_role;
select is(public.consume_reminder_invocation('88888888-8888-4888-8888-888888888888',floor(extract(epoch from now()))::bigint-180,'dispatch'),false,'expired capability cannot be consumed');
set local role anon;
select throws_ok($$select public.consume_reminder_invocation('77777777-7777-4777-8777-777777777777',floor(extract(epoch from now()))::bigint,'probe')$$,'42501',null,'anon cannot consume calls');
reset role;
update reminder_private.scheduler_config set enabled=true;
select is(reminder_private.dispatch_tick(false),null::uuid,'enabled scheduler with no due work avoids HTTP calls');
insert into net._http_response(id,status_code,content,timed_out) select request_id,200,'{"probe":true,"providerReady":true,"private_value":"must-not-persist"}',false from reminder_private.scheduler_invocations where request_id is not null;
select lives_ok($$select reminder_private.collect_scheduler_results()$$,'HTTP results are collected separately from Cron SQL success');
select ok((select summary='{"probe_ok":true,"delivery_enabled":false}'::jsonb and http_status=200 and completed_at is not null from reminder_private.scheduler_invocations where request_id is not null),'collection preserves only safe probe status');
select is((select summary->>'delivery_enabled' from reminder_private.scheduler_invocations where request_id is not null),'false','probe without enabled delivery cannot authorize activation');
select throws_ok($$select reminder_private.set_scheduler_enabled(true)$$,'22023',null,'HTTP success alone cannot activate without consumed probe');
update reminder_private.scheduler_invocations set used_at=now() where request_id is not null;
select throws_ok($$select reminder_private.set_scheduler_enabled(true)$$,'22023',null,'authenticated probe with delivery off still blocks activation');
select lives_ok($$select reminder_private.dispatch_tick(true)$$,'second probe may run after collecting first response');
insert into net._http_response(id,status_code,content,timed_out) select request_id,200,'{"probe":true,"providerReady":true,"deliveryEnabled":true,"private_value":"must-not-persist"}',false from reminder_private.scheduler_invocations where request_id is not null and completed_at is null;
update reminder_private.scheduler_invocations set used_at=now() where request_id is not null and completed_at is null;
select reminder_private.collect_scheduler_results();
select is(reminder_private.set_scheduler_enabled(true),true,'authenticated ready probe permits explicit activation');
select is((select active from cron.job where jobname='prazo-claro-reminders'),true,'activation changes the job and config together');
select reminder_private.prepare_scheduler();
select is((select active from cron.job where jobname='prazo-claro-reminders'),true,'preparation never resets an already active job');
select is(reminder_private.set_scheduler_enabled(false),false,'operator may disable immediately');
select is((select active from cron.job where jobname='prazo-claro-reminders'),false,'disabling also stops Cron');
insert into reminder_private.scheduler_invocations(nonce,issued_at,operation) values
('99999999-9999-4999-8999-999999999999',floor(extract(epoch from now()))::bigint,'probe');
set local role service_role;
select is(public.consume_reminder_invocation('99999999-9999-4999-8999-999999999999',floor(extract(epoch from now()))::bigint,'dispatch'),false,'operation is bound to the nonce');
select is(public.consume_reminder_invocation('99999999-9999-4999-8999-999999999999',floor(extract(epoch from now()))::bigint+1,'probe'),false,'timestamp must match the issued capability');
select is(public.consume_reminder_invocation('99999999-9999-4999-8999-999999999999',floor(extract(epoch from now()))::bigint,'probe'),true,'invalid attempts do not consume correct capability');
select throws_ok($$select reminder_private.dispatch_tick(true)$$,'42501',null,'service cannot issue scheduled calls');
select throws_ok($$select reminder_private.set_scheduler_enabled(true)$$,'42501',null,'service cannot activate Cron');
set local role authenticated;
select throws_ok($$select reminder_private.prepare_scheduler()$$,'42501',null,'user cannot prepare Cron');
reset role;
insert into reminder_private.scheduler_invocations(nonce,issued_at,operation,created_at) values
('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',floor(extract(epoch from now()))::bigint-691200,'probe',now()-interval '8 days');
select reminder_private.collect_scheduler_results();
select is((select count(*) from reminder_private.scheduler_invocations where nonce='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'),0::bigint,'operational metadata is pruned after seven days');
select * from finish();
rollback;
